import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
const local=process.argv.includes('--local'),base=local?new URL('public/writing/',import.meta.url).pathname.replace(/^\/(C:)/,'$1'):path.resolve('e73wgva4/data/writing');fs.mkdirSync(decodeURI(base),{recursive:true});const out=decodeURI(base);
const allRoster=local?JSON.parse(fs.readFileSync(new URL('private/inventory.json',import.meta.url))).profiles:JSON.parse(process.env.IELTS48_PARENT_ROSTER||'null');const roster=process.env.IELTS48_ONLY?allRoster.filter(p=>p.name===process.env.IELTS48_ONLY):allRoster;if(!Array.isArray(roster)||!roster.length)throw Error('ROSTER_SECRET_REQUIRED');
const main='https://script.google.com/macros/s/AKfycbyEtjxRQpIFsgZGzTHd0QpwvvjDhjQaPTpCeAdIPYEIuCElhgerif_1WcBh-iXOD3FV/exec',assessment='https://script.google.com/macros/s/AKfycbyCWtfi2hHWGut8qks2CKTa3q8QsUmoovYuAh83wORlMIhmaELYpWy6u5f36x36YTZWow/exec';
const key=(a,e={})=>a+'|'+JSON.stringify(Object.fromEntries(Object.entries(e).sort(([a],[b])=>a.localeCompare(b))));
async function callOnce(p,action,extra){const u=new URL(action.startsWith('writing_assessment')?assessment:main);Object.entries({api:'parent1',class:'IELTS 48',token:p.token,action,...extra}).forEach(([k,v])=>u.searchParams.set(k,v));const r=await fetch(u,{signal:AbortSignal.timeout(110000)});if(!r.ok)throw Error(action+'_HTTP_'+r.status);const v=await r.json();if(!v.ok&&v.error==='SOURCE_UNAVAILABLE')throw Error(action+'_SOURCE_UNAVAILABLE');if(!v.ok||!v.data||v.data.parentName!==p.name)throw Error(action+'_IDENTITY_OR_SOURCE');const raw=JSON.stringify(v.data);if(allRoster.some(row=>raw.includes(row.token)))throw Error('TOKEN_IN_SOURCE');return v.data;}
async function call(p,action,extra={}){try{return await callOnce(p,action,extra);}catch(e){if(e.name!=='TimeoutError'&&!/_HTTP_50[0234]$/.test(e.message)&&!/_SOURCE_UNAVAILABLE$/.test(e.message))throw e;await new Promise(resolve=>setTimeout(resolve,2000));return callOnce(p,action,extra);}}
const reports=[];let cursor=0;
async function worker(){while(cursor<roster.length){const p=roster[cursor++];try{
 const actions={},assets={},oldFile=path.join(out,p.hash+'.json');let old;try{old=JSON.parse(fs.readFileSync(oldFile));}catch(_){}
 actions[key('writing')]=await call(p,'writing');actions[key('classwork_index')]=await call(p,'classwork_index');
 async function detail(action,extra,version){const k=key(action,extra);if(old?.versions?.[k]===version&&old.actions[k]){actions[k]=old.actions[k];return;}const value=await call(p,action,extra),raw=JSON.stringify(value),hash=createHash('sha256').update(raw).digest('hex');if(raw.length>250000){const filename='asset-'+hash+'.json';assets[filename]=raw;actions[k]={staticAsset:filename};}else actions[k]=value;}
 const versions={};for(const r of actions[key('classwork_index')].reviews||[]){for(const [action,hash]of[['classwork_review',r.hash],['classwork_source',r.sourceHash]]){const extra={reviewKey:r.key,reviewHash:hash};versions[key(action,extra)]=hash;await detail(action,extra,hash);}}
 let packet;if(local)packet=JSON.parse(fs.readFileSync(new URL('private/profile-'+p.hash+'.json',import.meta.url)));else{const r=await fetch('https://ielts48-private-pilot.trangnga2024.workers.dev/data/'+p.hash+'.json');if(!r.ok)throw Error('PROFILE_UNAVAILABLE');packet=await r.json();}
 const descriptors=new Map((packet.actions.profile?.student?.assessmentResults||[]).flatMap(r=>r.components||[]).map(c=>c.writingAssessment).filter(d=>d?.available).map(d=>[JSON.stringify([d.assessmentKey,d.attempt,d.paper]),d]));
 for(const d of descriptors.values()){const extra={assessment_key:d.assessmentKey,attempt:String(d.attempt),paper:d.paper};for(const action of ['writing_assessment','writing_assessment_source']){versions[key(action,extra)]=d.payloadSha256;await detail(action,extra,d.payloadSha256);}}
 for(const [k,value]of Object.entries(actions)){if(value.staticAsset)continue;const raw=JSON.stringify(value);if(raw.length>50000){const filename='asset-'+createHash('sha256').update(raw).digest('hex')+'.json';assets[filename]=raw;actions[k]={staticAsset:filename};}}
 for(const [filename,raw]of Object.entries(assets))fs.writeFileSync(path.join(out,filename),raw);
 const result={schemaVersion:1,className:'IELTS 48',name:p.name,rosterRevision:packet.rosterRevision,capturedAt:new Date().toISOString(),actions,versions};
 if(old&&JSON.stringify(old.actions)===JSON.stringify(actions)&&JSON.stringify(old.versions)===JSON.stringify(versions))result.capturedAt=old.capturedAt;fs.writeFileSync(oldFile,JSON.stringify(result));reports.push({hash:p.hash,ok:true,actions:Object.keys(actions).length,bytes:fs.statSync(oldFile).size});console.log(JSON.stringify({completed:reports.length,total:roster.length,ok:true}));
 }catch(e){reports.push({hash:p.hash,ok:false,error:e.message});console.log(JSON.stringify({completed:reports.length,total:roster.length,ok:false,error:e.message}));}}}
await Promise.all([worker(),worker()]);
fs.writeFileSync(path.join(out,'export-report.json'),JSON.stringify({at:new Date().toISOString(),complete:reports.every(r=>r.ok),reports},null,2));if(reports.some(r=>!r.ok))process.exitCode=1;
